Image *ReadGroup4Image(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  FILE *input_file = NULL;
  FILE *temp_file = NULL;
  char temp_filename[MaxTextLength] = {0};

  if (image_info == NULL || exception == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      OptionError, "InvalidArgument", "Invalid image_info or exception pointer");
    return NULL;
  }

  input_file = fopen(image_info->filename, "rb");
  if (input_file == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      FileError, "UnableToOpenFile", "Unable to open input file: %s", image_info->filename);
    return NULL;
  }

  if (AcquireTempFile(temp_filename) != MagickTrue) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      FileError, "UnableToCreateTemporaryFile", "Unable to create temporary file");
    fclose(input_file);
    return NULL;
  }

  temp_file = fopen(temp_filename, "wb");
  if (temp_file == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      FileError, "UnableToOpenFile", "Unable to open temporary file: %s", temp_filename);
    fclose(input_file);
    return NULL;
  }

  if (WriteTIFFHeaders(temp_file, image_info, exception) != MagickTrue) {
    (void) fclose(temp_file);
    (void) fclose(input_file);
    (void) remove(temp_filename);
    return NULL;
  }

  if (WriteGroup4ImageData(temp_file, input_file, image_info, exception) != MagickTrue) {
    (void) fclose(temp_file);
    (void) fclose(input_file);
    (void) remove(temp_filename);
    return NULL;
  }

  (void) fclose(temp_file);
  (void) fclose(input_file);

  image = ReadImage(image_info, temp_filename, exception);
  if (image == NULL) {
    (void) remove(temp_filename);
    return NULL;
  }

  (void) remove(temp_filename);
  return image;
}
